use vstd::prelude::*;

verus! {
    fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
        requires
            a.len() < 0x1_0000_0000, // Ensure the length of the vector is within reasonable bounds to avoid overflow
        ensures
            result.len() == a.len() && // The output vector has the same length as the input vector
            forall|i: nat| (i < a.len() as nat) ==> (result[i] == a[i]), // For every valid index, the elements are equal
        decreases a.len() // Decrease clause to ensure termination
    {
        let mut result: Vec<T> = Vec::new(); // Initialize the result vector
        let mut idx: usize = 0; // Initialize the index

        while idx < a.len() // Loop until we have copied all elements
            invariant
                idx <= a.len(), // Ensure the index does not exceed the length of the input vector
                result.len() == idx, // The length of the result vector is equal to the index
                forall|i: nat| (i < idx as nat) ==> (result[i] == a[i]), // Elements copied so far are equal
            decreases a.len() - idx, // Decrease clause for termination
        {
            result.push(a[idx]); // Copy the element from input vector to result vector
            idx = idx + 1; // Increment the index
        }

        result // Return the copied vector
    }
}

